  "about.founder.p1": "大家好，我是康塞普西翁，Luminous StockHaven 的创始人。",
  "about.founder.p2": "我不是来自大型科技公司，也不在企业办公室里办公。我是一名小零售商，和你们一样。我经营着五家电子商务商店，专营图书和为爱书之人手工制作的配饰。\n和许多独立零售商一样，当我试图管理多个地点的库存、将出版商的 ISBN 与我自己的手工 SKU 一并跟踪，并用笨拙的电子表格处理供应商订单时，我达到了崩溃的边缘。当我寻找一款能帮助我的应用时，我试用了六种不同的选择。每一种要么完全不完整，要么令人难以置信地混乱，要么就是掠夺性的——为基本工具每月收取数百美元。",
  "about.founder.p3": "对这个盘剥独立创作者的行业感到沮丧后，我决定构建自己的解决方案。我出于必要性构建了 Luminous StockHaven，为了干净、高效、心安地经营我自己的生意。",
  "about.founder.p4": "我决定以诚实、实惠的价格向公众开放这个平台，因为每一位小商家都值得拥有真正好用、又不危及生计的工具。我们是独立拥有的，我们坚决守护我们的社区，我们由一位零售商为零售商们而建。",
