  "settings.security.changeEmailTitle": "更改您的账号邮箱",
  "settings.security.changeEmailDesc": "将您的账号转移到新邮箱。您的店铺、库存、团队和历史都会随之转移——且不会开始新的免费试用。所有其他已登录设备都会被登出。",
  "settings.security.newEmailLabel": "新邮箱",
