  "support.contextNote": "为了帮我们找到问题，您的留言会自动包含您所在的页面、您选择的企业和角色、您的套餐、应用语言，以及您使用的手机或浏览器类型。它永远不会包含您的产品、库存或销售。",
  "support.description": "有东西坏了、有东西看起来不对，或有想法要分享？请在这里告诉我们——您的留言会直接发给应用背后的团队。",
  "support.errorGeneric": "操作未成功。请重试。",
  "support.errorRateLimit": "您今天已发送了几份报告——谢谢。请等到明天再发送更多，以便每份报告都能被认真阅读。",
  "support.errorTooLong": "这超出了报告可容纳的长度——请稍微删减后重新发送。",
  "support.errorTooShort": "请多告诉我们一点——一两句话有助于我们找到问题。",
  "support.messageLabel": "发生了什么？",
  "support.messagePlaceholder": "用您自己的话告诉我们您当时在做什么、出了什么问题…",
  "support.sendAnother": "再发送一份报告",
  "support.sending": "正在发送…",
  "support.sentBody": "我们会阅读每份报告。如果需要更多详情，我们会写信到您的账号邮箱。",
  "support.sentTitle": "谢谢——您的报告已发送。",
  "support.submit": "发送报告",
  "support.title": "报告问题",
  "support.urgentNote": "是被锁在账号外面了？您的备用钥匙可以帮您回来——见上方的“安全与备用钥匙”，或使用登录页面上的恢复入口。",
  "training.lessons.mgr-report-problem.step1": "您的团队在收银台工作，问题最先在那里出现。如果应用对您团队中的任何人出现故障或行为异常，可以当场从“设置”的“报告问题”进行报告——由他们或由您报告。",
  "training.lessons.mgr-report-problem.step2": "请让他们讲清楚经过：他们当时在做什么、期望什么、实际发生了什么。一两句这样的描述胜过事后完美的描述。",
  "training.lessons.mgr-report-problem.step3": "报告会自行附上页面、门店、发送者的角色、套餐、应用语言和设备类型；产品、库存和销售永远不会附上。门店的任何数字都不会随报告离开。",
  "training.lessons.mgr-report-problem.step4": "报告会发给应用背后的团队，每一份都会被阅读。如果问题把某人锁在账号外，不要等待报告：备用钥匙和登录页面的恢复入口能让他们回来。",
  "training.lessons.mgr-report-problem.title": "当您的团队遇到问题时：报告它，不要绕过它",
  "training.lessons.owner-report-problem.step1": "您的订阅包含一条与构建此应用的人直接联系的渠道。打开“设置”，使用“报告问题”——它在每个套餐中都有，为您和您团队的每位成员提供。",
  "training.lessons.owner-report-problem.step2": "用您自己的话说明发生了什么：您当时想做什么，应用却做了什么。表单会自行附上修复所需的详情——页面、企业、角色、套餐、语言和设备；您的产品、库存和销售永远不会包含在内。",
  "training.lessons.owner-report-problem.step3": "每份报告都会被保存并由团队阅读。如果更多详情有帮助，他们会回复发送者的账号邮箱——这样答复能到达看到问题的人。",
  "training.lessons.owner-report-problem.step4": "一个例外：如果您或团队成员完全无法进入账号，报告不是最快的入口。备用钥匙（设置、安全与备用钥匙）和登录页面上的恢复入口正是为这种情况准备的。",
  "training.lessons.owner-report-problem.title": "报告问题：您与应用团队的直通线",
  "training.lessons.report-problem.step1": "如果应用中有东西坏了、看起来不对，或感觉不对，您不必忍受它。打开“设置”，找到“报告问题”——它为每个人提供，在每个套餐中都有。",
  "training.lessons.report-problem.step2": "选择您的留言是关于什么的——有东西坏了、有东西看起来不对、一个想法，或其他——然后用您自己的话写下发生了什么。您当时在做什么最有帮助。",
  "training.lessons.report-problem.step3": "您的留言会自动带有您所在的页面、您的门店和角色、套餐、应用语言，以及您使用的手机或浏览器类型——帮助找到问题的详情。它永远不会带有您的产品、库存或销售。",
  "training.lessons.report-problem.step4": "发送它，它会直接发给应用背后的团队，他们会阅读每份报告。如果他们需要更多详情，他们会写信到您的账号邮箱。是被锁在账号外面了？请使用您的备用钥匙或登录页面上的恢复入口——那些比报告更快。",
  "training.lessons.report-problem.title": "报告问题：有东西坏了就告诉我们",
  "crossStore.transferButton": "移动库存",
