  "crossStore.transferIntro": "两家店都是您的，所以您可以直接移动库存，无需申请。选择一个产品，说明数量和出发位置，再选择它到达的商店。两家店都会立即更新，并且都会保留这次移动的记录。",
  "crossStore.transferNoTargets": "您还没有另一家属于您的商店——库存只能在属于您的商店之间移动。",
