  "crossStore.transferToFirstLocation": "它的第一个位置",
  "crossStore.transferToLocation": "到位置",
  "training.lessons.owner-move-stock.step1": "申请是用来请求的；移动是店主的事。在跨店收件箱页面，“移动库存”面板让您——店主——把库存直接从这家店送到您拥有的另一家店，无需申请，也无需等待。",
  "training.lessons.owner-move-stock.step2": "选择产品、它出发的位置和数量。应用会显示该位置现有多少库存，一次移动绝不能超过这个数量。",
  "training.lessons.owner-move-stock.step3": "选择目标商店，如果愿意，还可以选择那里的确切位置。如果那家店已经有相同的 SKU，库存会并入该产品；如果没有，产品会连同库存一起复制过去。",
  "training.lessons.owner-move-stock.step4": "两家店都会保留记录：这家店显示转出，另一家显示接收。如果移动无法进行——库存不足，或者另一家店不是您的——任何东西都不会移动，应用会说明原因。",
  "training.lessons.owner-move-stock.title": "在您自己的商店之间移动库存（Business 计划）",
  "plansLib.feature.pricing": "清仓与限时特价定价",
  "plansLib.includes.pricing": "清仓和限时特价销售定价",
  "pricing.businessOnly": "清仓和限时特价定价属于 Business 计划。",
  "pricing.clearanceBadge": "清仓",
  "pricing.clearanceHint": "永久降价。它会一直保持，直到您改回常规价格。",
  "pricing.clearancePriceLabel": "清仓价",
  "pricing.endLabel": "结束",
  "pricing.modeClearance": "清仓",
  "pricing.modeLabel": "定价",
  "pricing.modeRegular": "常规价格",
  "pricing.modeRollback": "限时特价（临时促销）",
  "pricing.rollbackBadge": "限时特价",
  "pricing.rollbackHint": "在促销期间，常规价格会被保留，并显示在特价旁边。结束日期过后，价格会自动恢复为常规价格。",
  "pricing.rollbackStarts": "限时特价将于 {date} 开始",
  "pricing.salePriceLabel": "特价",
  "pricing.sectionTitle": "销售定价",
  "pricing.startLabel": "开始",
  "training.lessons.mgr-pricing.step1": "在 Business 上，产品表单有一个“销售定价”部分。清仓是永久降价——设定后就保持不变。限时特价是带日期的促销：设定特价、开始日期和结束日期。",
  "training.lessons.mgr-pricing.step2": "您永远不必重新输入常规价格：它保留在产品上，并显示在产品列表和扫描器中的特价旁边，这样任何人都能看到该商品通常的价格。",
  "training.lessons.mgr-pricing.step3": "限时特价开始时打印新的价格标签——标签打印的是客户当天支付的价格。结束日期过后，价格会自动恢复为常规价格；在您刷新货架时重新打印常规标签。",
  "training.lessons.mgr-pricing.step4": "如果“销售定价”部分显示为锁定，说明该企业不在 Business 计划上——销售定价属于该计划，只有店主才能更改计划。",
  "training.lessons.mgr-pricing.title": "做促销：清仓与限时特价",
  "training.lessons.owner-pricing.step1": "产品表单中的“销售定价”下有两种降价。清仓是永久的：设定清仓价后，它会一直保持低价，直到您改回来。限时特价是临时促销——一个更低的价格，带有开始日期和结束日期，就像您在大商店里已经熟悉的促销一样。",
  "training.lessons.owner-pricing.step2": "常规价格永远不会被抹掉。限时特价运行期间，应用会显示特价，并在旁边显示常规价格；打印的标签使用特价，这样货架与收银台一致。",
  "training.lessons.owner-pricing.step3": "结束日期过后，价格会自动回到常规价格——无需记住任何事情，也无需撤销。尚未开始的限时特价会在产品列表上直接说明它的开始日期。",
  "training.lessons.owner-pricing.step4": "销售定价是 Business 计划的功能。在 Essentials 上，这些字段保持锁定；如果一家企业降到 Essentials 后再回来，它的清仓和限时特价设置仍然原封不动，正如当初离开时一样。",
  "training.lessons.owner-pricing.title": "清仓与限时特价定价（Business 计划）",
