  "training.lessons.owner-shipping-labels.step1": "打印中心在两种套餐中都有\"邮寄标签\"样式：选择一个客户订单，即可打印一张 4×6 标签，上面有买家姓名和地址，以及作为寄件人的您的店铺。",
  "training.lessons.owner-shipping-labels.step2": "这张标签和所有客户单据一样是白标的：上面只有您的店铺名称——绝不会出现本应用的名称——所以从您店里寄出的包裹看起来就是来自您的店。",
  "training.lessons.owner-shipping-labels.step3": "客户的地址会随其订单保留到最后一次订单后 90 天；如果订单存有地址，标签会从该地址开始；打印时为一次性标签输入的地址不会被保存回去。姓名仍会从订单填入，这样标签与单据一致。",
  "training.lessons.owner-shipping-labels.step4": "这张标签通过与所有标签相同的四种连接打印——蓝牙、Wi-Fi、以太网和 USB——4×6 热敏打印机是它的标准尺寸。",
  "training.lessons.owner-shipping-labels.step5": "改为向承运商购买了邮资？在同一区域，您可以上传承运商的标签文件 — PDF、PNG 或 JPG — 它会永久保存在订单上：您的记录，以防万一，随时都在手边。它以真实的 4×6 尺寸打印。本应用从不出售邮资，所以承运商的价格是唯一的价格 — 并且永远是正确的价格。",
  "training.lessons.owner-shipping-labels.title": "客户订单邮寄标签",
  "training.lessons.print-shipping-label.step1": "订单准备好寄出时，打开打印中心，选择\"邮寄标签\"样式，再选择客户订单。买家姓名会从订单自动填入。",
  "training.lessons.print-shipping-label.step2": "检查包裹要寄往的地址。当订单带有客户地址时 — 会保留到最后一次订单后 90 天 — 它会自动填入；您在打印时输入的地址不会被保存回去，所以打印前请仔细核对邮编和最后一行。",
  "training.lessons.print-shipping-label.step3": "您的店铺名称会作为寄件人打印在顶部。如果还想把您的地址也印在标签上，把它输入寄件人地址栏；不想出现就留空。",
  "training.lessons.print-shipping-label.step4": "用 4×6 标签打印——热敏标签打印机是常见选择——或通过浏览器打印按钮用任何打印机打印。把标签平贴在包裹上，不要折到边缘。",
  "training.lessons.print-shipping-label.step5": "如果邮资是向承运商购买的，请改为把他们的标签文件保存在订单上：在“您的承运商标签”区域上传承运商给您的 PDF、PNG 或 JPG。它会作为您的记录留在订单上，并以真实的 4×6 尺寸打印 — 而当您更愿意使用时，应用自己的地址标签也随时都在。",
  "training.lessons.print-shipping-label.title": "打印邮寄标签",
