  "staffWelcome.editor.permanentNote": "第一行是应用本身 — 它始终显示，无法更改或删除。",
  "staffWelcome.editor.tokens": "在应该出现此人名字的地方写 {name}，在应该出现您的店名的地方写 {store} — 应用会为每个人填好。",
  "staffWelcome.editor.emptyNote": "将框留空即可使用应用的标准欢迎语（在框中淡淡地显示）。新员工永远不会看到空白页面。",
  "staffWelcome.editor.save": "保存欢迎消息",
  "staffWelcome.editor.saved": "欢迎消息已保存。",
  "training.lessons.staff-shift-windows.title": "您的登录跟随您的班次",
  "training.lessons.staff-shift-windows.step1": "您可以从预定班次开始前约 10 分钟起登录。在此之前，应用保持关闭 — 登录页面会告诉您下一个班次何时开始。",
  "training.lessons.staff-shift-windows.step2": "一旦您打卡下班，您有 10 分钟查看您的页面，因为您将被退出，直到您的下一个预定日期。",
  "training.lessons.staff-shift-windows.step3": "如果您在这 10 分钟内重新打卡上班，退出将被取消，您将保持登录状态。",
  "training.lessons.staff-shift-windows.step4": "排班表上没有班次意味着那天无法登录。如果您认为自己应该在排班表上，请询问您的经理或所有者 — 发布打开您大门的排班表的是他们。",
  "training.lessons.manager-shift-windows.title": "发布排班表会打开和关闭访问权限",
  "training.lessons.manager-shift-windows.step1": "您为团队发布的排班表不仅仅是班次列表：它打开和关闭每个人的应用访问权限。团队成员可以从您为他发布的班次前约 10 分钟起登录 — 不能更早。",
  "training.lessons.manager-shift-windows.step2": "当他打卡下班时，他有大约 10 分钟查看他的时间，然后应用会将他退出，直到他的下一个预定班次。那天没有发布班次意味着他那天无法登录。",
  "training.lessons.manager-shift-windows.step3": "请谨慎发布班次：缺失或错误的班次会把一个人锁在应用之外，而不仅仅是排班表之外。如果有人说他进不来，请先检查他的排班表。",
  "training.lessons.manager-shift-windows.step4": "您自己的访问权限也以同样的方式运作，只是高一个级别：所有者为您发布的排班表会在您的班次前约 10 分钟打开您的窗口，并在您打卡下班后约 10 分钟关闭您的会话。",
  "training.lessons.owner-shift-windows.title": "班次窗口：排班表打开和关闭访问权限",
  "training.lessons.owner-shift-windows.step1": "访问权限跟随您发布的排班表。员工或经理可以从其预定班次前约 10 分钟起登录 — 不能更早。在班次之外，应用对他们保持关闭，这样店的信息就留在值班人员手中。",
  "training.lessons.owner-shift-windows.step2": "当他们打卡下班时，他们有大约 10 分钟查看他们的时间，然后应用会自行将他们退出，直到他们的下一个预定班次。在这 10 分钟内重新打卡上班会取消退出。",
  "training.lessons.owner-shift-windows.step3": "那天没有发布班次意味着那天没有窗口：如果某人不在排班表上，他就无法登录。在劳动力中发布排班表，他的大门就会随之打开。",
  "training.lessons.owner-shift-windows.step4": "您是唯一的例外：没有人给所有者排班，所以您的登录永远没有窗口。经理受您为他发布的排班表的限制，就像员工受为他们发布的排班表的限制一样。",
  "settings.install.ownerNote": "如果您的应用商店哪天让您无法使用该应用，此链接可让您直接从本网站获取应用 — 无需商店。",
