  "apiErrors.invalidValue.recordingNotPrepared": "该录音无法准备 — 请重新录制。",
  "training.lessons.messages-private.step5": "您也可以发送语音留言：点按消息框旁边的麦克风，说话，然后点按停止。先听一遍 — 然后发送，或者删除后重新录制。当有人发给您时，点按播放即可听到对方真实的声音。",
  "training.lessons.owner-messages-oversight.step5": "已读标记：当团队成员阅读了您发送的消息时，您会看到它被标记为已读。员工和经理以同样的方式互相看到对方的已读标记，双向都是如此。",
  "training.lessons.owner-messages-oversight.step6": "您自己的阅读是不可见的。当您阅读员工发给您的消息时，对方永远不会看到已读标记 — 而且您不需要告诉团队，他们的对话保存在应用中，而您作为店主可以阅读它们。这种监督是您照看店铺的一部分。",
  "training.lessons.owner-messages-oversight.step7": "对于员工之间的负面消息，您如何处理由您决定。可以置之不理，私下与某人谈谈，或者采取行动 — 选择权在您，您永远不需要说出您是在哪里看到的。",
  "staffLib.perm.returnsComplete": "完成退款和换货",
  "staffLib.area.returnsAccess": "退货审批",
  "staff.memberDialog.returnsAccessHint": "勾选此项后，此人可以审批退货并完成退款或换货。没有勾选时，他们发起的退货会等待店主或经批准的团队成员处理。",
