  "apiErrors.locationsCreateReserved": "只有店主，或经店主允许添加位置的团队成员，才能添加位置。",
  "settings.policies.title": "您商店的政策与条款",
  "settings.policies.ownerDescription": "您的商店,您的规则。在这里写下您商店的政策和条款 — 可以直接输入,也可以上传文件。每位新团队成员在开始时都会看到一次,您的整个团队随时可以在这里阅读。只有您可以更改它们。",
  "settings.policies.memberDescription": "您商店自己的政策和条款,由店主撰写。只有店主可以更改它们。",
