  "settings.platformPolicies.description": "应用本身的条款和政策。它们与应用一起保留,团队中的每个人都可以在这里阅读。",
  "staffWelcome.policiesIntro": "在您开始之前:您商店的政策和条款,由店主撰写。",
  "plansLib.includes.storePolicies": "在设置中您自己的商店政策和条款,供您的整个团队阅读",
