  "training.lessons.owner-store-policies.title": "您商店的政策与条款",
  "training.lessons.owner-store-policies.step1": "打开设置,找到“商店政策与条款”卡片。它包含两份文档:您的商店政策 — 您商店的内部规则 — 以及您的条款与条件。",
  "training.lessons.owner-store-policies.step2": "每份文档都可以直接在那里输入,或作为文件上传(PDF、文字、Word 或 OpenDocument,最大 25 MB)。两者只能选其一:保存文字会替换文件,上传文件会替换文字。移除一份文档会将其清空。",
  "training.lessons.owner-store-policies.step3": "您的团队会在他们第一次开始时的欢迎页面上看到这两份文档一次,并且随时可以在他们的设置中阅读。对您的团队来说,它们是只读的 — 只有您可以撰写或更改它们。",
  "training.lessons.owner-store-policies.step4": "每个商家都保存自己的文档:您在这里写的内容只属于这家商店,永远不会出现在另一家商家中。Luminous StockHaven 自己的条款和政策位于设置中您文档的旁边,每个人也可以阅读它们。",
  "training.lessons.welcome-basics.step5": "您商店的政策和条款会在您的欢迎页面上显示一次,并保存在设置中,您随时可以在那里阅读。",
