  "settings.policyQuiz.title": "给您团队的问题",
  "staff.memberDialog.trainingAccessHint": "阅读店铺政策和条款是面向所有人的。这些勾选项分配的是所有者在设置中每份文件旁边建立的测验培训。",
  "staffLib.area.trainingAccess": "政策测验培训",
  "staffLib.perm.trainingPoliciesQuiz": "店铺政策测验培训",
  "staffLib.perm.trainingTermsQuiz": "条款与条件测验培训",
  "training.comment.placeholder": "关于这节课的任何想法…",
  "training.comment.send": "发送留言",
  "training.comment.sent": "您的留言已提交给所有者。",
  "training.comment.title": "给所有者留言",
  "training.lessons.download-app.step1": "Luminous StockHaven 可以像真正的应用一样装在您的手机或电脑上 — 不需要应用商店。",
  "training.lessons.download-app.step2": "打开设置，找到下载应用卡片。每个角色、两种套餐都有这张卡片。",
  "training.lessons.download-app.step3": "点安装按钮，按设备的提示操作。应用会带着店铺的名称和图标出现在主屏幕上。",
  "training.lessons.download-app.step4": "从那以后就从主屏幕打开它 — 登录方式相同，显示的也是同一家店铺。",
  "training.lessons.download-app.title": "把应用下载到您的设备",
  "training.lessons.mgr-tax-rate.step1": "订单可以带一个销售税率。税率本身由所有者在设置中设定；整个店铺只有一个税率。",
  "training.lessons.mgr-tax-rate.step2": "当所有者在您的员工记录中为您勾选税费部分时，税率也会出现在您的设置中，您可以在那里保持它最新。",
  "training.lessons.mgr-tax-rate.step3": "税率是一个百分比 — 8.25 表示顾客在订单商品金额之外还要付 8.25% 的税。",
  "training.lessons.mgr-tax-rate.step4": "税率变化时，新订单使用新税率。已经下的订单保留下单时的税率。",
  "training.lessons.mgr-tax-rate.step5": "如果店主将税额切换为自动，新订单会在州出现在订单上的那一刻，用客户所在州的基本税率填入税额，州变更时还会重新填入。这些是各州的基本税率；地方税可能还会增加。没有州、或来自美国境外的订单，使用商店的固定税率——而在订单上输入的税额始终优先。",
  "training.lessons.mgr-tax-rate.title": "店铺的税率",
  "training.lessons.owner-confidentiality.step5": "这是全貌。您的团队看到的是他们自己的工作 — 他们的排班、任务、工资单、消息，以及他们角色能打开的店铺页面。他们永远看不到您的试用、企业用的是哪个套餐、套餐多少钱、付款是否成功，或者是否达到了套餐上限。涉及钱的页面 — 账单、发票、付款方式 — 永远只有所有者能看。",
  "training.lessons.owner-confidentiality.step6": "如果账户被停用，您的团队看到的正是这条消息：“更改目前已关闭。目前无法添加或更改任何内容 — 如果您需要什么，请询问商家所有者。” 其中没有提到套餐、价格或付款。",
  "training.lessons.owner-confidentiality.step7": "而当套餐上限导致某事被拦下时，显示的正是这条消息：“现在无法添加这个 — 请向企业所有者询问。” 它从不说达到了上限 — 那只在您和应用之间。",
  "training.lessons.staff-builds.step1": "组合是把产品拼成一个可以出售的东西 — 礼包、套装、礼品套装。组合在菜单的组合页面里。",
  "training.lessons.staff-builds.step2": "打开一个组合，查看它的组成：每个部件产品，以及组合各用多少个。",
  "training.lessons.staff-builds.step3": "组合被制作或售出时，其部件的库存会随之变动 — 应用会为您保持数量准确。",
  "training.lessons.staff-builds.step4": "如果缺少某个部件或数量看起来不对，请告诉您的经理，不要猜测 — 组合会同时影响许多产品。",
  "training.lessons.staff-builds.title": "组合与礼包",
  "training.lessons.staff-cross-store.step1": "当您的企业有不止一家店铺或网点时，店铺之间可以互相请求库存。这些请求会进入跨店收件箱。",
  "training.lessons.staff-cross-store.step2": "从菜单打开收件箱，查看另一家店铺在请求什么，以及您的店铺收到了什么。",
  "training.lessons.staff-cross-store.step3": "只按经理教您的方式回复请求 — 发出库存会改变您自己店铺的数量。",
  "training.lessons.staff-cross-store.step4": "如果请求看起来不对 — 物品错了，或者数量超过您有的 — 不要猜。请向经理报告。",
  "training.lessons.staff-cross-store.title": "跨店收件箱",
  "training.lessons.staff-reports.step1": "报表把店铺的数字 — 销售、库存等等 — 汇总到一处。报表在菜单里。",
  "training.lessons.staff-reports.step2": "打开一份报表，查看它所涵盖日期的数字。日期是报表的一部分：同一份报表换一周，讲的就是另一个故事。",
  "training.lessons.staff-reports.step3": "有些报表可以保存为文件导出。只有在经理或所有者要求时，才把报表导出保存。",
  "training.lessons.staff-reports.step4": "报表的数字来自店铺的真实工作 — 订单、盘点和调动 — 所以其他地方都如实录入，报表才会真实。",
  "training.lessons.staff-reports.title": "阅读报表",
  "training.lessons.welcome-basics.step6": "完成后请退出登录：每个页面最底部、版权行正上方都有一个退出登录链接。退出登录会在所有设备上都退出 — 这样就没人能在共用屏幕上进入您的账户。",
  "training.policy.belowLine": "这低于及格线 — 再试一次吧。",
