  "training.lessons.your-profile-photo.title": "您的个人资料照片",
  "training.lessons.your-profile-photo.step1": "所有者批准后，您的照片会出现在应用顶部您的名字旁边、「员工」页面上，以及您的消息旁边。在此之前，只会显示您的姓名缩写。",
  "training.lessons.your-profile-photo.step2": "打开「设置」，找到「您的个人资料照片」。选择一张您自己的照片并发送。它会发送给所有者批准——在等待期间不会出现在任何地方。",
  "training.lessons.your-profile-photo.step3": "所有者批准后，您的铃铛会响起，您的照片开始显示。如果未获批准，请选择一张不同的照片并重新发送。",
  "training.lessons.your-profile-photo.step4": "更换照片的方式相同：新照片等待批准，在新照片获批之前，您的当前照片保持不变。如果更换未获批准，您保留原来的照片。",
  "training.lessons.owner-profile-photos.title": "个人资料照片与您的名字",
  "training.lessons.owner-profile-photos.step1": "每个人的照片都会显示在其名字旁边——在应用顶部、您的「员工」页面上，以及他们的消息旁边。团队成员的照片在您批准之前不会出现在任何地方——批准权只属于您，任何人都不能批准自己的照片。",
  "training.lessons.owner-profile-photos.step2": "当有人发送照片时，您的铃铛会响起。打开「员工」页面查看，然后选择「批准」或「不批准」。如果您不批准，系统会通知对方选择另一张照片。",
  "training.lessons.owner-profile-photos.step3": "如果有人更换照片，新照片同样等待您的批准。在等待期间，他们的当前照片保持不变——如果您不批准更换，它也会继续保留。",
  "training.lessons.owner-profile-photos.step4": "您自己的照片无需批准：在「设置」的「您的个人资料照片」下设置。同一张卡片还包含您的名字——您在那里设置的名字会在团队看到的所有地方取代「所有者」这个词，包括应用内和「消息」中。",
