  "training.lessons.mgr-clock-callin.title": "临时叫班与考勤修正",
  "training.lessons.mgr-clock-callin.step1": "店主可以给经理两个分开的勾。临时叫班让您可以为一名员工打开叫班窗口，考勤牌与漏打的下班卡让您可以查看团队的考勤牌，并在员工页面修正考勤记录。每个勾都独立起作用 — 经理可以只有其中一个。",
  "training.lessons.mgr-clock-callin.step2": "叫班窗口让一个人在没有班次覆盖时也能登录并打卡。在员工页面，从“叫班与漏打下班卡”卡片打开它。",
  "training.lessons.mgr-clock-callin.step3": "窗口会一直开着，直到那个人打了下班卡 — 之后是通常的10分钟登出宽限 — 或者直到您或店主提前关闭它。没有任何东西会自动关闭它。",
  "training.lessons.mgr-clock-callin.step4": "当有人忘记打下班卡时，排班一结束，他的记录就会在员工页面和工资单中被标记，您和店主都会收到通知。记录会一直计时，直到被修正。",
  "training.lessons.mgr-clock-callin.step5": "在员工页面修正记录：设置上班、下班和休息时间。经理只能修正员工的记录 — 经理自己的记录由店主修正。",
