  "staff.documents.mineTitle": "我的文件",
  "staff.documents.mineDesc": "您的店主为您保存在档案中的文书 — W-4 表格、您的求职申请、税务表格、身份证件副本。这是您自己的档案：其中任何内容您都可以打开、下载和打印，但这里的任何内容都不能更改。",
