  "nav.xstoreMessages": "跨店消息",
  "plansLib.businessIncludes.xstoreMessages": "跨店消息——您的整个团队，遍及每一家企业",
  "xstore.title": "跨店消息",
  "xstore.help": "此账户的每一个人，遍及您的所有企业，都汇集在一个收件箱中。您可以在这里给他们任何人发消息——文字或语音，并带有送达和已读标记。您的店内消息保持不变。",
  "xstore.empty": "还没有对话。用“新消息”开始一段对话吧。",
  "xstore.noPeople": "还没有其他人可以发消息。人们加入您的某家企业并登录后，就会显示在这里。",
  "xstore.deliveredLabel": "已送达",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "跨店消息是商业版套餐的一部分。",
  "apiErrors.invalidValue.personNotPartAccount": "那个人不属于此账户。",
  "training.lessons.owner-xstore-messages.title": "跨店消息，店主篇",
  "training.lessons.owner-xstore-messages.step1": "跨店消息是第二个收件箱，与店内消息分开。店内消息用于您当前所在的商店；而这个入口可以联系到您账户上的每一个人，遍及您拥有的每一家企业——最多五家。",
  "training.lessons.owner-xstore-messages.step2": "从菜单打开跨店消息，即可与列表上的任何人开始对话。列表会显示您所有企业中已登录的每一位团队成员，以及他们工作的商店。",
  "training.lessons.owner-xstore-messages.step3": "照片也会一同显示：每个人都会显示其已获批准的个人资料照片，没有照片时则显示姓名首字母。每条消息都带有发送的日期和时间。",
  "training.lessons.owner-xstore-messages.step4": "在您自己发送的消息下方，消息送达后您会看到“已送达”，对方打开对话后会看到“已读”。语音留言在这里也能使用，与店内消息完全一样。",
  "training.lessons.owner-xstore-messages.step5": "这里的对话仅对对话中的两个人私密。您对店内消息的查看权限不会延伸到其他商店。",
  "training.lessons.mgr-xstore-messages.title": "跨店消息，经理篇",
  "training.lessons.mgr-xstore-messages.step1": "跨店消息可以联系到此账户上的每一个人，遍及每一家企业——而不仅仅是您当前所在的商店。它位于菜单中，与店内消息分开。",
  "training.lessons.mgr-xstore-messages.step2": "从列表开始一段对话：每一位已登录的团队成员都在那里，姓名旁标注着他们工作的商店。",
  "training.lessons.mgr-xstore-messages.step3": "发送文字，或者录制语音留言。语音留言发送前，您可以回听、丢弃或发送——与店内消息一样。",
  "training.lessons.mgr-xstore-messages.step4": "您的消息送达时会显示“已送达”，对方打开对话时会显示“已读”。每个姓名旁的照片是该人已获批准的个人资料照片。",
  "training.lessons.staff-xstore-messages.title": "跨店消息",
  "training.lessons.staff-xstore-messages.step1": "跨店消息让您可以联系到此账户上的任何人，无论他们在店主的哪一家企业——向另一家商店提问，再也不必等待。",
  "training.lessons.staff-xstore-messages.step2": "从菜单打开它，选择对方，然后写消息。如果您需要的人不在列表中，说明他们还没有登录——他们一登录就会显示出来。",
  "training.lessons.staff-xstore-messages.step3": "您也可以在这里发送语音留言：录制、回听，然后发送或丢弃。每条消息都会显示发送的日期和时间。",
  "training.lessons.staff-xstore-messages.step4": "当您发送消息时，送达后会显示“已送达”，对方打开对话后会显示“已读”。对话仅对您和对方私密。",
