  "training.lessons.owner-restaurant-ops.title": "餐厅运营，店主版",
  "training.lessons.owner-restaurant-ops.step1": "供应商发票位于餐厅专区。录入供应商开出的账单，关联到其采购订单，应用会三方核对——已订购、已收货和已开票，并列显示——并标记任何短缺、超量或以不同价格开票的行。",
  "training.lessons.owner-restaurant-ops.step2": "当发票行以与记录成本不同的价格为产品开票时，发票页面会打开价格提醒。接受提醒会将产品成本更新为开票价格；忽略它则保持成本不变。",
  "training.lessons.owner-restaurant-ops.step3": "损耗记录会记录厨房扔掉的一切，附原因——变质、生产过剩、备餐失误、退回、洒漏或其他——记录它会自动将库存从货架扣除。保质期批次按先到期先出列出，因此最早的保质期先被使用，您可以为您勾选的批次打印日期标签。",
  "training.lessons.owner-restaurant-ops.step4": "过敏原矩阵根据每道菜配方的配料，对照九大主要过敏原计算其过敏原，让客人的问题从记录中得到回答，而不是凭记忆。温度记录、沽清看板和员工餐对整个团队开放——无需勾选——因为日常记录只有在任何人都能做时才行得通。",
  "training.lessons.owner-restaurant-ops.step5": "菜单工程按每道菜的销量和收益定位：明星、耕马、谜题和瘦狗。差异页面将配方说本应离架的与员工餐、损耗和所有其他出库进行比较——剩下的就是无法解释的部分。会计导出将已收货采购、损耗、员工餐和配方扣减汇总成一本账，供您入账。",
  "training.lessons.staff-restaurant-daily.title": "厨房的日常习惯",
  "training.lessons.staff-restaurant-daily.step1": "当有东西被扔掉时，当天就在损耗记录中记录：是什么、多少，以及原因——变质、生产过剩、备餐失误、退回、洒漏或其他。记录它会自动将库存从货架扣除；您无需单独调整库存。",
  "training.lessons.staff-restaurant-daily.step2": "在检查每个冰箱、冷冻柜和保温温度时记录它。记录会保留您的姓名和时间，并标记任何超出安全范围的读数——将您对此采取的措施写为纠正措施。",
  "training.lessons.staff-restaurant-daily.step3": "沽清看板就是现在什么卖完了。物品一卖完就贴上，让整个团队立刻知道，补货后清除——看板会保留清除人和时间。",
  "training.lessons.staff-restaurant-daily.step4": "当团队用餐时，将其记录为员工餐。每份餐都会将其菜品从货架扣除，并使用该菜品配方的配料，如同一次销售。员工餐是一天的真实成本，应该记录在案。",
  "training.lessons.mgr-restaurant-invoices.title": "发票、批次和批次运行",
  "training.lessons.mgr-restaurant-invoices.step1": "店主已将“制作配方”勾选托付给您，它也开启了厨房的制作工作：供应商发票、保质期批次和批量生产。录入带行的供应商发票——产品、数量和开票成本——并在有采购订单时将其关联。",
  "training.lessons.mgr-restaurant-invoices.step2": "关联采购订单后，发票会逐行三方核对：订购了什么、收货了什么、开票了什么。一行可能返回匹配、短缺、超量、以不同价格开票，或根本不在订单上。",
  "training.lessons.mgr-restaurant-invoices.step3": "当开票价格与产品记录成本不同时，会打开价格提醒。接受提醒会将产品成本设为新的开票价格；忽略它则什么都不改变。同一发票和产品同时只有一个打开的提醒。",
  "training.lessons.mgr-restaurant-invoices.step4": "将库存作为带保质期的批次收货，保质期页面会保持批次先到期先出。批次运行将一个配方制作指定份数：它用掉配方的配料，并将成品备餐产品放到货架上——配方必须先关联到该备餐产品。",
  "training.lessons.mgr-restaurant-invoices.step5": "当供应商针对发票退回款项时——破损的箱子、短缺的交货、修正的价格——在发票页面上针对该发票将其记录为贷项通知单。供应商来自发票本身，通知单计入发票仍欠的金额：发票显示其已应用的贷项和应付余额。贷项永远不能超过其发票，作废通知单会将其留在记录中，同时停止计数。 需要纸质版时，可从该行打印此凭证——打印出的单据是您对供应商贷项的自有记录，并非供应商的单据。",
  "training.lessons.mgr-restaurant-reports.title": "菜单工程、差异和账目",
  "training.lessons.mgr-restaurant-reports.step1": "店主已将“菜品金额”勾选托付给您，它也开启了厨房的金额报表：菜单工程、差异和会计导出。这些数字留在企业内部，如同所有菜品金额。",
  "training.lessons.mgr-restaurant-reports.step2": "菜单工程按每道菜在该期间的销量和收益定位。明星销量好、收益好；耕马销量好但收益少；谜题收益好但销量少；瘦狗两者都不行。",
  "training.lessons.mgr-restaurant-reports.step3": "差异页面按产品工作：配方说本应离架的，与员工餐、损耗和所有其他出库并列。剩下的一切都是无法解释的——而无法解释的正是需要去解释的数字。",
  "training.lessons.mgr-restaurant-reports.step4": "会计导出是厨房的一本账：已收货采购、损耗、员工餐和配方扣减，每行带其日期、数量和成本，可交给记账人。",
