  "storefronts.ebayDesc": "将您的 eBay 店面连接一次。当商品在 eBay 上售出时，其数量会在这里自动减少，销售会记录在您的出入库记录中 — 就像它被扫码出库一样。销售只单向流动：从 eBay 流入应用。",
