  "plansLib.includes.recordPrints": "纸质记录 — 每周排班表、工资登记表、工时表、培训记录、政策与条款、员工名册和价格清单，可打印已填写版或手填空白版",
  "training.lessons.staff-record-prints.title": "纸上的记录",
  "training.lessons.staff-record-prints.step1": "应用中几乎每条记录现在在文档样式工作室里都有一个纸质孪生版：每周排班表、工资登记表、工时表、培训记录、您店铺的政策与条款、员工名册和产品与价格清单 — 在 Business 套餐中还有供应商目录和已填写的温度记录。每份都以您保存的文档样式、您企业的语言打印，日期按您的方式书写。",
  "training.lessons.staff-record-prints.step2": "每份纸都在其记录所在之处。在员工页面，排班标签打印您能看到的每个人的整周安排，考勤标签从其记录打印工时表。打印只显示您在该屏幕上已经能看到的内容 — 打印永远不会扩大任何人的可见范围。",
  "training.lessons.staff-record-prints.step3": "在工资页面，预览一个工资期间并打印登记表：每个人、其工时、总额、扣除和净额都在一张纸上，供工资档案使用。在培训页面，团队部分打印培训记录 — 谁完成了什么，附测验分数和日期。",
  "training.lessons.staff-record-prints.step4": "您店铺的政策与条款从设置中打印，与您所写的完全一致，可交到新员工手里或贴在墙上。员工页面打印一页名册，产品页面打印价格清单，在 Business 中供应商页面打印目录，温度记录页面为食品安全档案打印已填写的记录。",
  "training.lessons.staff-record-prints.step5": "需要一张手填的表格吗？打印中心的空白表格现在为这些纸张中的每一份都提供空白孪生版，两个套餐都有：打印一张，用笔填好，与打印件放在一起归档。",
  "ageCheck.title": "年龄检查",
  "ageCheck.intro": "扫描驾驶证或身份证背面的条形码。你只会得到一个答案——绿色对勾或红色对勾——而应用不会保留扫描中的任何信息：没有姓名，没有号码，没有出生日期，没有任何记录。",
  "ageCheck.scanPrompt": "将摄像头对准证件或卡片背面的条形码。",
  "ageCheck.categoryLabel": "正在卖什么？",
  "ageCheck.category.alcohol": "酒类",
  "ageCheck.category.tobacco": "烟草",
  "ageCheck.category.other": "其他有年龄限制的商品",
  "ageCheck.lineNote": "你对{category}的界线：{age}岁及以上",
  "ageCheck.pass": "年龄足够——可以出售。",
  "ageCheck.fail": "年龄不够——不要进行这笔交易。",
  "ageCheck.expired": "这张证件已过期——不通过。",
  "ageCheck.unreadable": "那个码不是我们能读取的身份证条形码。请试试证件背面的条形码。",
  "ageCheck.checkAnother": "再检查一个",
  "ageCheck.back": "返回扫描产品",
  "ageCheck.keepsNothing": "这次扫描的任何信息都不会被保存、发送或记录。答案就是全部，离开此屏幕后就会消失。",
  "settings.ageLines.title": "年龄界线",
  "settings.ageLines.description": "顾客在每种交易中必须达到的年龄，扫描页面的年龄检查使用它。这些界线由你来设定——请按照你的企业所在地的法律来设定。应用以酒类21岁、烟草21岁、其他有年龄限制的商品18岁为起点。",
  "settings.ageLines.alcohol": "酒类——最低年龄",
  "settings.ageLines.tobacco": "烟草——最低年龄",
  "settings.ageLines.other": "其他有年龄限制的商品——最低年龄",
  "plansLib.includes.ageCheck": "用证件扫描进行年龄检查——扫描身份证背面获得绿色或红色对勾，证件中的任何信息都不会被保留",
  "training.lessons.scanner-age-check.title": "用证件扫描检查年龄",
  "training.lessons.scanner-age-check.step1": "有些商品只能出售给超过一定年龄的顾客。在扫描页面，打开年龄检查，选择正在卖什么——酒类、烟草，或其他有年龄限制的商品——然后扫描顾客驾驶证或身份证背面的条形码。",
  "training.lessons.scanner-age-check.step2": "答案是两个对勾中的一个。绿色对勾表示顾客年龄足够，可以出售。红色对勾表示他还没有达到该类别的界线，或者证件已过期——无论哪种情况，都不应进行交易。",
  "training.lessons.scanner-age-check.step3": "应用不会保留扫描中的任何信息。任何姓名、证件号码或出生日期都不会在任何地方被保存、发送或记录：检查回答那一个问题后便消失。没有已检查证件的清单可供回看——这是有意为之。",
  "training.lessons.scanner-age-check.step4": "年龄界线属于店主，他在设置中按照企业所在地的法律来设定。它们可以因地而异，也可以与应用的起始界线不同，而检查始终遵循你所在企业的店主界线。",
  "training.lessons.scanner-age-check.step5": "如果码无法读取，屏幕会明确说明。擦拭条形码后再试一次，或要求出示另一张证件。不是身份证条形码的码永远不会获得绿色对勾。",
  "training.heading.general": "通用培训",
  "training.heading.restaurant": "餐厅培训",
