  "training.own.sectionTitle": "来自店主的培训",
  "training.own.sectionHelp": "您的店主为这家店写了这些培训。逐个阅读，然后回答店主的问题。",
  "training.own.read": "培训",
  "training.own.noMaterial": "店主还没有添加培训文字。",
  "training.own.pendingNote": "您的答案在店主那里。当店主标记为通过时，这个培训才算完成。",
  "plansLib.includes.ownTraining": "添加您自己的培训——为您的团队编写自己的培训和测验",
  "training.lessons.owner-own-training.title": "添加您自己的培训",
  "training.lessons.owner-own-training.step1": "在培训页面的最末尾有“添加您自己的培训”框。打开它，开始一个新培训，并给它一个标题——您的安全规则、您的注意事项、您做事的方式。",
  "training.lessons.owner-own-training.step2": "在框里用您自己的话写下培训内容本身，或者改为上传文件——PDF、文本、Word 或 OpenDocument 文件。输入的文字会替换已保存的文件，文件也会替换输入的文字。",
  "training.lessons.owner-own-training.step3": "在下面创建它的测验：想出多少题都可以，选择题和书面回答题自由混合。对于书面题，写下您期望的答案；对于选择题，标记正确的那个。",
  "training.lessons.owner-own-training.step4": "设定通过线，并选择书面回答的判定方式：用您的答案钥匙几乎逐字核对，或者发给您来标记通过或退回。然后准确勾选哪些团队成员参加这个培训——只有他们能看到它。",
  "training.lessons.owner-own-training.step5": "您保存的每个培训都在框里独立存在，有自己的问题、通过线和勾选，您可以添加任意多个。结果会出现在每个培训下方的框里；只有当服务器核查了一次通过的作答，培训才算完成——或者在批改模式下，当您标记为通过时。",
  "apiErrors.ownTrainingOwnerWrites": "这些培训只有店主能写。",
  "apiErrors.ownTrainingNotHere": "那个培训不在这里。",
  "apiErrors.ownTrainingTooLong": "那个培训太长，无法在这里输入。您可以改为上传文件。",
  "apiErrors.ownTrainingTicksList": "请将勾选的人以列表形式发送。",
  "apiErrors.ownTrainingTickNotTeam": "勾选的人中有一人不在这个团队里。",
  "apiErrors.ownTrainingNoFile": "没有为那个培训保存文件。",
  "apiErrors.ownTrainingWrittenMode": "书面回答会用钥匙核对，或发送给店主。",
  "print.pool.title": "生成条形码",
  "print.pool.intro": "在商品存在之前就生成条形码。把它们打印出来，贴在没有自己条形码的商品上；日后扫描其中一个时，应用会认出这个码，并提议添加该商品。",
  "print.pool.countLabel": "您需要多少个条形码？",
  "print.pool.generate": "生成",
  "print.pool.generating": "正在生成…",
  "print.pool.minted": "已向您的码池添加 {count} 个新条形码。",
  "print.pool.waiting": "您的码池中有 {count} 个未使用的条形码在等待。",
  "print.pool.printNow": "立即打印",
  "print.pool.savePdf": "保存为 PDF",
  "print.pool.failed": "无法生成那些条形码。请重试。",
  "scan.pool.title": "您自己打印的条形码之一",
  "scan.pool.body": "这还不是您店里的商品——这是您预先打印的条形码。您想把它添加为商品吗？",
  "plansLib.includes.barcodePool": "条形码池——预先打印条形码，然后在每个商品的条形码被扫描时添加该商品",
  "training.lessons.owner-barcode-pool.title": "在商品之前打印条形码",
  "training.lessons.owner-barcode-pool.step1": "有些商品没有自己的条形码——手工制品、您自己的书包、任何您亲手制作或组合的东西。在打印部分，“生成条形码”入口会在商品存在之前就生成编码。",
  "training.lessons.owner-barcode-pool.step2": "说出您需要的数量——没有上限——应用就会向您企业的条形码池铸造同样数量的新码。它们只属于您的企业，绝不会发放两次，生成它们也不会产生商品或库存。",
  "training.lessons.owner-barcode-pool.step3": "在它们生成的那一刻做出选择：立即打印成标签，或保存为 PDF 以便日后打印。无论哪种方式，这些码都在池中，打印出的标签与码池完全一致。",
  "training.lessons.owner-barcode-pool.step4": "在制作每件商品时给它贴上一个标签。未使用的码只是在池中等待——不用着急，它们也不会过期。",
  "training.lessons.owner-barcode-pool.step5": "当贴有标签的商品日后被扫描时，应用会认出它自己打印的码，并提议添加该商品，码已经填好。添加之后，这个码就成为该商品的码，像其他任何码一样被扫描。",
  "apiErrors.poolOwnerMints": "只有店主才能为码池生成条形码。",
  "apiErrors.poolCount": "说出您需要多少个条形码——一个整数，一个或更多。",
  "nav.checklists": "清单",
  "plansLib.includes.checklists": "清单——开店、打烊、清洁等等,在手机上勾选,在重要的地方附上证明",
  "staffLib.perm.checklistsManage": "清单模板与分配",
