  "training.lessons.staff-checklists.title": "做清单",
  "training.lessons.staff-checklists.step1": "清单是您的生意运转所靠的清单——开店、打烊、清洁,以及店主设定的一切。在“清单”里找到它们:今天的清单在最上面,准备好勾选。",
  "training.lessons.staff-checklists.step2": "当您真正做完一个项目时再勾选它。每个勾选都会记下是谁做的、什么时候做的,这样下一个人——以及在家的店主——都能看到什么做完了、什么还缺。",
  "training.lessons.staff-checklists.step3": "有些项目在勾选前要求证明:做完工作的照片、代码的扫描,或输入的温度。先添加证明,再勾选——没有证明,项目不会被勾选。",
  "training.lessons.staff-checklists.step4": "不小心勾选了什么?取消它的勾选——但只能取消自己的。经理或店主可以取消任何人的,因为勾选是带名字的记录。",
  "training.lessons.staff-checklists.step5": "做清单从来不需要许可。建立模板并选择分配给谁是店主的工作,或店主给予清单模板勾选的人的工作。",
