  "training.lessons.staff-equipment.title": "设备记录与报告故障",
  "training.lessons.staff-equipment.step1": "您生意中的每台机器在设备中都有自己的页面：何时购买、保修何时结束、由谁维修，以及发生过的一切。",
  "training.lessons.staff-equipment.step2": "当有东西坏了时，就在机器本身上报告。说出什么坏了，如果可以，附上问题照片 — 报告会带着您的名字和时间进入机器的历史。",
  "training.lessons.staff-equipment.step3": "只有当店主授予您故障报告勾选时，您才能报告故障。如果按钮不在那里，请告诉店主或经理，他们会为您开门。",
  "training.lessons.staff-equipment.step4": "保养任务 — 清洁、除垢、维修 — 都有到期日期。设备页面显示哪些到期、哪些逾期，让任何事都不悄悄溜走。",
  "training.lessons.staff-equipment.step5": "维修及其费用由店主或经理记录。当针对您的报告记录了维修后，故障会在机器历史中显示为已修好。",
