  "training.lessons.owner-tip-pooling.title": "小费池与小费记录",
  "training.lessons.owner-tip-pooling.step1": "打开餐厅，再打开团队与地点，再打开小费池。只有店主能看到小费池设置、份额和记录。",
  "training.lessons.owner-tip-pooling.step2": "选择小费池如何分：按小时、按岗位百分比或按点数。应用会根据已有的排班和打卡小时来分。",
  "training.lessons.owner-tip-pooling.step3": "选择期间，输入小费池金额，预览分配，然后保存。保存的份额会进入该期间的工资预览。",
  "training.lessons.owner-tip-pooling.step4": "准备好时发布已保存的分配 — 团队成员那时只能看到自己的份额，发布之前什么也看不到。",
  "training.lessons.owner-tip-pooling.step5": "随时保存小费记录：按人、按期间、所报小费 — 年记录会把 8% 的计算换算成表格可用的合计。应用只保存记录；不提交任何东西。",
