  "training.lessons.owner-labor-warnings.title": "设定人工警告",
  "training.lessons.owner-labor-warnings.step1": "打开排班表，找到盯守数字。那里的每个数字都由您为自己的店设定。",
  "training.lessons.owner-labor-warnings.step2": "设定对您来说加班从每周多少小时开始，以及在应用警告您之前，有人可以接近到什么程度。",
  "training.lessons.owner-labor-warnings.step3": "设定一个班次中何时应有休息、休息应有多长，以及您希望班次内最早的开始和最晚的结束。",
  "training.lessons.owner-labor-warnings.step4": "像往常一样排这一周。当小时接近您的线时，警告会出现在排班表上——在它们越线之前。",
  "training.lessons.owner-labor-warnings.step5": "随着团队打卡进出，同样的盯守也会扫过已工作的小时，包括没有休的休息。",
  "training.lessons.owner-labor-target.title": "按人工目标排这一周",
  "training.lessons.owner-labor-target.step1": "在餐厅角的团队与场所货架上打开人工目标。",
  "training.lessons.owner-labor-target.step2": "以百分比输入您的人工目标，以及您预计本周的销售额。",
  "training.lessons.owner-labor-target.step3": "在排班表上排这一周。预计人工成本及其%会根据应用中已有的班次和时薪更新。",
  "training.lessons.owner-labor-target.step4": "当预计人工%超过您的目标时，页面会用明白的话说出来，并附上背后的小时和成本。",
  "training.lessons.owner-labor-target.step5": "当您想把这一周打印在纸上时，从页面打印——打印出的表格与您在屏幕上看到的是同一份文件。",
