  "training.lessons.owner-reservations.title": "接受预订并管理候位名单",
  "training.lessons.owner-reservations.step1": "在餐厅角的“餐区与客人”货架上打开“预订”。预订簿保存每一个预订；它下面的候位名单保存今晚直接到店的客人。",
  "training.lessons.owner-reservations.step2": "添加预订时填写日期和时间、团体的名称和人数、电话号码，以及用您自己的话写的桌台或区域。记下厨房需要知道的事——过敏、高脚椅、纪念日。",
  "training.lessons.owner-reservations.step3": "询问客人是否想要提醒，只有在他们说“好”时才勾选该框。提醒通过电子邮件发送，短信设置好后也通过短信发送。把已收的定金——金额和方式——只作为记录写下。",
  "training.lessons.owner-reservations.step4": "整晚推进预订簿：将每个团体标记为已入座、未到或已取消。从预订簿将今天的名单发送给团队，让每个人都从同一页工作。",
  "training.lessons.owner-reservations.step5": "对于直接到店的客人，将团体连同告知的等待时间加入候位名单。当他们的桌台准备好时，点击“桌台已准备好”——为那条短信提供号码，就是客人的同意。",
  "apiErrors.smsInvalid": "一条短信需要一个号码和一条消息。",
  "apiErrors.smsFailed": "短信服务未接受该消息。",
