  "training.lessons.owner-standing-orders.title": "常订订单与供应商价格比较",
  "training.lessons.owner-standing-orders.step1": "在餐厅角的库存与订购货架上打开常订订单。你的重复订单在这里，它们的下方是供应商价格簿。",
  "training.lessons.owner-standing-orders.step2": "将常订订单设置一次：给它起个名字，选择它的供应商和对应的日子，并以你通常订购的数量添加常备货行。",
  "training.lessons.owner-standing-orders.step3": "到了那天，点按生成本周草稿。本应用会在采购部写入一份草稿采购订单，按价格簿中该供应商的最新价格计价 — 请审阅、修改任何需要的内容，并由你亲自发送。本应用绝不会自行发送订单。",
  "training.lessons.owner-standing-orders.step4": "订购前先读价格簿：一种食材，每个供应商的最新价格并排比较，最便宜的在前，附有日期以及该价格来自发票还是订单。",
  "training.lessons.owner-standing-orders.step5": "供应商发票一到就录入，让价格簿保持真实 — 每个新价格都会加入价格簿，下一份草稿将据此计价。",
