  "training.lessons.owner-production-order.title": "按生产下单与自动填写的备餐单",
  "training.lessons.owner-production-order.step1": "在餐厅角的库存与订货货架上打开按生产下单。生产计划 — 一次批量生产或一场餐饮活动 — 在这里变成食材订单。",
  "training.lessons.owner-production-order.step2": "选择计划：批量生产选食谱和份数，或选一场你已预订的餐饮活动。点击计算订单。",
  "training.lessons.owner-production-order.step3": "应用会展开食谱，减去已有库存，其余向上取整到包装规格，并按供应商分组 — 订货指南的样式。",
  "training.lessons.owner-production-order.step4": "点击生成草稿订单，每个供应商一张草稿采购单进入采购环节。请自行审核并发送 — 应用绝不会自行发送订单。",
  "training.lessons.owner-production-order.step5": "在备餐页，备餐单会自动填写：建议份数来自你的标准库存量、预订和活动中的预订情况，以及已备好的数量 — 建议只展示，在你运行批量生产之前什么都不会变。",
  "nav.barCounting": "酒吧盘点",
  "restaurant.doorBarCounting": "酒吧盘点 — 按存放区域以十分之一为单位盘点开瓶，并以同样方式记录桶",
  "plansLib.businessIncludes.barCounting": "用于半瓶和桶的酒吧盘点",
  "barCounting.title": "酒吧盘点",
  "barCounting.subtitle": "按存放区域盘点已开封的物品。将滑块移到开瓶看起来有多满 — 以十分之一为单位 — 并以同样方式记录桶。满瓶和满桶按整瓶整桶计。",
  "barCounting.offTitle": "酒吧盘点已关闭",
  "barCounting.offBody": "酒吧盘点在店主开启之前保持隐藏。只有当此商家设有酒吧时才开启 — 它会出现在库存与订货货架上。",
