  "barCounting.varianceNote": "保存的酒吧盘点是一个盘点会话：它与记录的差异是理论与实际差异的实际一侧。",
  "apiErrors.barCountingForbidden": "只有店主才能开启或关闭酒吧盘点。",
  "apiErrors.barCountingCountForbidden": "只有店主、经理或拥有盘点权限的人才能保存酒吧盘点。",
