  "apiErrors.barCountingOff": "此商家未开启酒吧盘点。",
  "training.lessons.owner-bar-counting.title": "盘点酒吧：半瓶和桶",
  "training.lessons.owner-bar-counting.step1": "从库存与订货货架开启酒吧盘点 — 在你开启之前它保持隐藏，所以没有酒吧的商家永远看不到它。开关只属于店主。",
  "training.lessons.owner-bar-counting.step2": "打开酒吧盘点，选择你所站的存放区域。该表列出该区域所存物品，每瓶和每桶旁边都有记录在册的数量。",
  "training.lessons.owner-bar-counting.step3": "每一行说明是瓶还是桶，输入满的数量，然后将滑块移到开的那瓶看起来有多满 — 以十分之一为单位，对照它的图片判断。盘点数是满的数量加上开瓶的十分之几。",
  "training.lessons.owner-bar-counting.step4": "保存酒吧盘点。它会作为普通盘点会话到达盘点 — 送去复核并在那里应用，货架就会设为你盘点的数量。",
  "training.lessons.owner-bar-counting.step5": "酒吧盘点发现的差异会汇入理论与实际差异，所以总是短缺的瓶子会在那里显形。当你想把盘点印在纸上时，从此页面打印盘点表。",
