  "training.lessons.owner-locations-rollup.title": "所有门店在一页上",
  "training.lessons.owner-locations-rollup.step1": "打开门店货架并选择所有门店。货架本身只有在您拥有两个或更多企业时才出现,因此只有一个门店的店主永远看不到它。",
  "training.lessons.owner-locations-rollup.step2": "阅读每个门店的行:食材成本 %、库存价值、本周浪费和库存不足。突出的那个门店就是要先处理的薄弱环节。",
  "training.lessons.owner-locations-rollup.step3": "当您想把比较结果印在纸上时,打印汇总 — 它会按屏幕上的样子打印。",
  "training.lessons.owner-locations-rollup.step4": "要复制配方,请选择它,勾选它应到达的门店,然后复制。配料先按 SKU 匹配,再按名称匹配;没有匹配的会在结果中被点名,绝不会被悄悄丢弃。",
  "training.lessons.owner-locations-rollup.step5": "要复制价格,请使用相同的门店勾选来复制价格和成本。配方若其菜品在某个门店没有匹配,就会以草稿形式到达那里,等您来关联。",
