  "ops.invoices.acceptNote": "接受一张发票会使其价格成为其配料的当前成本，而使用这些配料的每个菜谱都会重新计算自身成本——菜谱会显示一条注明其所依据发票价格的备注。",
  "training.lessons.owner-recipe-cost-link.title": "菜谱成本跟随发票价格",
  "training.lessons.owner-recipe-cost-link.step1": "在与送货核对时，将供应商发票以草稿形式录入。",
  "training.lessons.owner-recipe-cost-link.step2": "当发票无误时，将其状态设为已接受。",
  "training.lessons.owner-recipe-cost-link.step3": "接受它会使每个开票价格成为该配料的当前成本。",
  "training.lessons.owner-recipe-cost-link.step4": "使用该配料的每个菜谱都会立即根据新价格重新计算成本。",
  "training.lessons.owner-recipe-cost-link.step5": "打开一个菜谱，查看其成本更新备注，其中注明了它所依据的发票价格——成本从不悄悄改变。",
