  "training.lessons.owner-shift-swaps.step1": "打开团队排班表，找到换班标签页。任何团队成员都可以在那里提出班次。",
  "training.lessons.owner-shift-swaps.step2": "团队成员把班次放到池子里，同岗位的任何同事都可以接，或者向一位同事提出交换。",
