  "training.lessons.owner-lot-traceability.title": "批次代码、召回和供应商可追溯性",
  "training.lessons.owner-lot-traceability.step1": "送货到达时，打开库存与订购货架上的“批次与召回”并记录：产品、供应商、数量 — 以及每个物品箱子上盖印的批次代码。",
  "training.lessons.owner-lot-traceability.step2": "在同一个后门屏幕上，记录冷藏品的送货温度，以及您拒收的任何东西及原因。书面拒收正是供应商贷记所需的证据。",
  "training.lessons.owner-lot-traceability.step3": "对于按重量出售的商品，记录到达的实际重量。应用程序据此计算每磅或每公斤的真实成本，使食谱成本保持诚实。",
  "training.lessons.owner-lot-traceability.step4": "如果批次被召回，请将其下架：批次被锁定以便无人能使用，下架本身成为记录，剩余部分连同原因流入废弃日志。",
  "training.lessons.owner-lot-traceability.step5": "使用召回查找器和可追溯性日志回答批次在哪里、去过哪里 — 按供应商或按批次 — 并为卫生部门或供应商打印日志。",
