  "training.lessons.owner-spill-log.title": "洒出与破损日志",
  "training.lessons.owner-spill-log.step1": "先开启吧台盘点：洒出与破损日志和吧台家族一起住在库存与订货货架上，它的门出现在吧台盘点旁边。",
  "training.lessons.owner-spill-log.step2": "有东西洒出或打碎时，立即记录：物品、洒出或打碎了多少、是洒出还是破损。",
  "training.lessons.owner-spill-log.step3": "一定要写原因 — 发生了什么。没有原因的洒出会被拒绝，因为原因就是记录本身。",
  "training.lessons.owner-spill-log.step4": "这条记录按废弃日志的方式计为损失：库存通过一笔核销移动离开，一行带成本的记录落入废弃日志，这样差异和总账只看到它一次。",
  "training.lessons.owner-spill-log.step5": "洒出酒水的成本只有店主能看到 — 这次洒出让吧台花了多少。需要纸质版时，从它的页面打印日志。",
