  "training.lessons.staff-pest-calibration.title": "虫害防治与温度计校准",
  "training.lessons.staff-pest-calibration.step1": "在食品安全货架的“虫害与校准”下找到这两个记录 — 它们与食品安全档案一起存放，并打印在检查就绪包中。",
  "training.lessons.staff-pest-calibration.step2": "每次虫害服务上门后，记录一行：日期、公司、技术员、处理区域、他们的发现，以及下次上门到期时间。",
  "training.lessons.staff-pest-calibration.step3": "把虫害公司自己的报告与上门一起归档 — 在记录表单上附上它，它会与记录一起留给检查员。",
  "training.lessons.staff-pest-calibration.step4": "用冰水检查温度计：把温度计放在冰水中，记录是哪支温度计、它显示的读数，以及你的姓名缩写。",
  "training.lessons.staff-pest-calibration.step5": "冰水中的温度计必须读出 32 °F (0 °C)：读到这个数值检查通过，读到任何其他数值，记录会显示温度计已被调整 — 这份记录正是温度记录的凭证。",
